#!/usr/bin/env python3
"""Regenerates components/icon.slint from the SVG files in assets/icons.

Slint resolves `@image-url` at compile time, so the Icon component lists every file literally.
Run after adding or removing an icon.
"""
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
names = sorted(p.stem for p in (root / "assets" / "icons").glob("*.svg"))
lines = [
    "// Icons drawn for LunaDash (assets/icons). Generated by scripts/gen-icons.py.",
    "",
    "export component Icon inherits Image {",
    "    in property <string> name;",
    "    in property <color> color: white;",
    "    colorize: root.color;",
    "    image-fit: contain;",
    "    width: 20px;",
    "    height: 20px;",
    "    source:",
]
lines += [f'        root.name == "{n}" ? @image-url("../assets/icons/{n}.svg") :' for n in names]
lines += ['        @image-url("../assets/icons/info.svg");', "}"]
(root / "components" / "icon.slint").write_text("\n".join(lines) + "\n")
print(f"{len(names)} icons")
